package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_indexOf_TriageGen0Test {

    @Test
    public void testIndexOf_NullString() {
        StrBuilder sb = new StrBuilder("hello");
        assertEquals(-1, sb.indexOf(null, 0));
        assertEquals(-1, sb.indexOf(null, 2));
    }

    @Test
    public void testIndexOf_EmptyString() {
        StrBuilder sb = new StrBuilder("hello");
        // If strLen == 0, returns startIndex
        assertEquals(0, sb.indexOf("", 0));
        assertEquals(2, sb.indexOf("", 2));
        assertEquals(5, sb.indexOf("", 5));
    }

    @Test
    public void testIndexOf_SingleCharString() {
        StrBuilder sb = new StrBuilder("banana");
        // strLen == 1 triggers indexOf(char, int)
        assertEquals(1, sb.indexOf("a", 0));
        assertEquals(3, sb.indexOf("a", 2));
        assertEquals(-1, sb.indexOf("z", 0));
    }

    @Test
    public void testIndexOf_StartIndexOutOfBounds() {
        StrBuilder sb = new StrBuilder("hello");
        // startIndex >= size returns -1
        assertEquals(-1, sb.indexOf("h", 5));
        assertEquals(-1, sb.indexOf("h", 10));
        // startIndex < 0 is treated as 0
        assertEquals(0, sb.indexOf("h", -5));
    }

    @Test
    public void testIndexOf_StringLongerThanBuilder() {
        StrBuilder sb = new StrBuilder("abc");
        // strLen > size returns -1
        assertEquals(-1, sb.indexOf("abcd", 0));
    }

    @Test
    public void testIndexOf_FoundAtStart() {
        StrBuilder sb = new StrBuilder("teststring");
        assertEquals(0, sb.indexOf("test", 0));
    }

    @Test
    public void testIndexOf_FoundInMiddle() {
        StrBuilder sb = new StrBuilder("teststring");
        assertEquals(4, sb.indexOf("string", 0));
        assertEquals(4, sb.indexOf("string", 2));
    }

    @Test
    public void testIndexOf_NotFound() {
        StrBuilder sb = new StrBuilder("teststring");
        assertEquals(-1, sb.indexOf("missing", 0));
        assertEquals(-1, sb.indexOf("test", 5));
    }

    @Test
    public void testIndexOf_OverlappingPatterns() {
        // Testing the loop logic with potential partial matches
        StrBuilder sb = new StrBuilder("aaaaa");
        assertEquals(0, sb.indexOf("aa", 0));
        assertEquals(1, sb.indexOf("aa", 1));
        assertEquals(3, sb.indexOf("aa", 3));
    }

    @Test
    public void testIndexOf_ExactMatch() {
        StrBuilder sb = new StrBuilder("abc");
        assertEquals(0, sb.indexOf("abc", 0));
    }

    @Test
    public void testIndexOf_EdgeCaseLoopEnd() {
        // The loop condition is i < len where len = thisBuf.length - strLen
        // This tests if the very last possible position is reachable
        StrBuilder sb = new StrBuilder("abcdef");
        assertEquals(3, sb.indexOf("def", 0));
    }
}
